import json,os,pathlib,subprocess,time,shutil,re
svc='jellyfin-pink.service'
root=pathlib.Path('/srv/projects/jellyfin-server')
def run(args,timeout=12):
 try:
  p=subprocess.run(args,capture_output=True,text=True,timeout=timeout)
  return p.returncode,p.stdout,p.stderr
 except subprocess.TimeoutExpired:
  return 124,'','timeout'
def property(name):
 c,v,_=run(['systemctl','show',svc,'-p',name,'--value'])
 return v.strip() if c==0 else None
assert property('User')=='jellyfinpink'
assert property('ActiveState')=='active'
def health():
 return {s:run(['systemctl','is-active',s])[1].strip() for s in ('vivoapk-backend.service',svc,'nginx.service','postgresql.service')}
before=health()
assert all(v=='active' for v in before.values())
mem={}
for line in pathlib.Path('/proc/meminfo').read_text().splitlines():
 k,_,v=line.partition(':')
 if k in ('MemTotal','MemAvailable'):
  mem[k]=int(v.strip().split()[0])*1024
capacity={'logical_cpu_count':os.cpu_count(),'load_average':list(os.getloadavg()),'memory_bytes':mem,'disk_free_bytes':shutil.disk_usage(root).free,'service_cpu_quota':property('CPUQuotaPerSecUSec'),'service_memory_max':property('MemoryMax'),'service_tasks_max':property('TasksMax'),'hardware_acceleration': 'not tested'}
results=[]
if mem['MemAvailable']<768*1024*1024 or os.getloadavg()[0]>=max(1,(os.cpu_count() or 1)*0.75):
 print(json.dumps({'scope':'synthetic capacity preflight; no media access','capacity':capacity,'status':'skipped_due_to_resource_load','services':before}),flush=True)
else:
 for width,height in ((1280,720),(1920,1080)):
  assert all(v=='active' for v in health().values())
  cmd=['sudo','-n','-u','jellyfinpink','--','/usr/bin/ffmpeg','-hide_banner','-nostdin','-v','error','-nostats','-progress','pipe:1','-filter_threads','1','-filter_complex_threads','1','-f','lavfi','-i',f'testsrc2=size={width}x{height}:rate=25','-f','lavfi','-i','sine=frequency=500:sample_rate=48000','-t','4','-c:v','libx264','-threads:v','2','-preset','veryfast','-pix_fmt','yuv420p','-b:v','2500k' if height==720 else '4500k','-c:a','aac','-b:a','128k','-threads:a','1','-f','null','-']
  start=time.monotonic()
  c,o,e=run(cmd,25)
  elapsed=time.monotonic()-start
  fields={}
  for line in o.splitlines():
   key,sep,value=line.partition('=')
   if sep:fields[key]=value
  frame=int(fields.get('frame','0').strip() or '0')
  speed=fields.get('speed','').strip()
  r={'resolution':f'{width}x{height}','duration_seconds':4,'frames':frame,'elapsed_seconds':round(elapsed,3),'ffmpeg_reported_speed':speed,'real_time_factor_including_startup':round(4/elapsed,2),'exit':c,'finished':fields.get('progress')=='end','thread_limit':2}
  results.append(r)
  if c!=0 or frame<100 or fields.get('progress')!='end':
   r['failure_category']='timeout' if c==124 else ('permission_denied' if 'permission denied' in e.lower() or 'not allowed' in e.lower() else 'encoder_or_progress_failure')
   break
  time.sleep(1)
 after=health()
 report={'scope':'short generated synthetic H264/AAC encoding to null; single job outside service cgroup; no live input, client, concurrency or production deployment certification','capacity':capacity,'benchmarks':results,'services_before':before,'services_after':after,'status':'completed' if len(results)==2 and all(r['exit']==0 and r['finished'] and r['frames']>=100 for r in results) else 'partial'}
 print(json.dumps(report),flush=True)
 assert before==after
 assert report['status']=='completed'
